package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

type User struct {
	ID       string
	Username string
	Role     string
	Token    string
	Password string
}

type AuditEntry struct {
	Timestamp time.Time
	Action    string
	UserID    string
	Details   string
}

var (
	users    = make(map[string]*User)
	sessions = make(map[string]*User)
	auditLog []AuditEntry
	mu       sync.RWMutex
)

func init() {
	users["admin"] = &User{ID: "1", Username: "admin", Role: "admin", Password: "change-me-admin"}
	users["user1"] = &User{ID: "2", Username: "user1", Role: "viewer", Password: "change-me-user1"}
}

func generateToken() string {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		// Fail closed: never emit a token derived from insufficient entropy.
		panic(fmt.Sprintf("failed to generate secure token: %v", err))
	}
	return hex.EncodeToString(b)
}

func authenticate(r *http.Request) *User {
	token := r.Header.Get("X-Auth-Token")
	if token == "" {
		return nil
	}
	mu.RLock()
	defer mu.RUnlock()
	return sessions[token]
}

func requireRole(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			user := authenticate(r)
			if user == nil {
				http.Error(w, "Unauthorized", http.StatusUnauthorized)
				return
			}
			for _, role := range roles {
				if user.Role == role {
					next(w, r)
					return
				}
			}
			http.Error(w, "Forbidden", http.StatusForbidden)
		}
	}
}

func sanitizeHeaderValue(val string) string {
	var builder strings.Builder
	for _, ch := range val {
		if ch == '\r' || ch == '\n' {
			continue
		}
		builder.WriteRune(ch)
	}
	return builder.String()
}

func encodeDisplayName(name string) string {
	// Encode for safe display in response headers
	// Strip all control characters including CR and LF
	var builder strings.Builder
	for _, ch := range name {
		if ch < 0x20 || ch == 0x7F {
			builder.WriteString(fmt.Sprintf("%%%02X", ch))
		} else {
			builder.WriteRune(ch)
		}
	}
	return builder.String()
}

func normalizeForAudit(input string) string {
	// Normalize unicode and strip non-printable for audit logging
	normalized := strings.ToValidUTF8(input, "")
	var builder strings.Builder
	for _, ch := range normalized {
		if ch >= 0x20 && ch != 0x7F {
			builder.WriteRune(ch)
		}
	}
	return builder.String()
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	username := r.FormValue("username")
	password := r.FormValue("password")
	deviceName := r.FormValue("device_name")

	mu.RLock()
	user, exists := users[username]
	mu.RUnlock()

	// Verify credentials with a constant-time comparison to avoid timing leaks.
	if !exists || subtle.ConstantTimeCompare([]byte(user.Password), []byte(password)) != 1 {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	token := generateToken()
	mu.Lock()
	user.Token = token
	sessions[token] = user
	auditLog = append(auditLog, AuditEntry{
		Timestamp: time.Now(),
		Action:    "login",
		UserID:    user.ID,
		Details:   normalizeForAudit(fmt.Sprintf("device=%s", deviceName)),
	})
	mu.Unlock()

	safeDevice := sanitizeHeaderValue(deviceName)
	w.Header().Set("X-Auth-Token", token)
	w.Header().Set("X-Device-Echo", safeDevice)
	w.Header().Set("X-User-Role", user.Role)
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"ok"}`))
}

func profileHandler(w http.ResponseWriter, r *http.Request) {
	user := authenticate(r)
	if user == nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if r.Method == http.MethodPut {
		displayName := r.FormValue("display_name")
		encoded := encodeDisplayName(displayName)
		// Set custom header for mobile client SDK consumption
		w.Header().Set("X-Display-Name", encoded)
		w.Header().Set("X-Profile-Updated", "true")
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(fmt.Sprintf(`{"display_name":"%s"}`, encoded)))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(fmt.Sprintf(`{"username":"%s","role":"%s"}`, user.Username, user.Role)))
}

func deviceRegistrationHandler(w http.ResponseWriter, r *http.Request) {
	user := authenticate(r)
	if user == nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	pushToken := r.FormValue("push_token")
	platform := r.FormValue("platform")
	deviceModel := r.FormValue("model")

	// Validate platform
	if platform != "ios" && platform != "android" {
		http.Error(w, "Invalid platform", http.StatusBadRequest)
		return
	}

	// Echo device info back in headers for client SDK verification
	cleanPush := sanitizeHeaderValue(pushToken)
	cleanModel := sanitizeHeaderValue(deviceModel)

	w.Header().Set("X-Push-Registered", cleanPush)
	w.Header().Set("X-Device-Model", cleanModel)
	w.Header().Set("X-Platform", platform)

	mu.Lock()
	auditLog = append(auditLog, AuditEntry{
		Timestamp: time.Now(),
		Action:    "device_register",
		UserID:    user.ID,
		Details:   normalizeForAudit(fmt.Sprintf("platform=%s,model=%s", platform, deviceModel)),
	})
	mu.Unlock()

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"registered":true}`))
}

func adminAuditHandler(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()

	w.Header().Set("Content-Type", "application/json")
	var sb strings.Builder
	sb.WriteString("[")
	for i, entry := range auditLog {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(fmt.Sprintf(`{"ts":"%s","action":"%s","user":"%s","details":"%s"}`,
			entry.Timestamp.Format(time.RFC3339), entry.Action, entry.UserID, entry.Details))
	}
	sb.WriteString("]")
	w.Write([]byte(sb.String()))
}

func main() {
	mux := http.NewServeMux()

	mux.HandleFunc("/api/v1/login", loginHandler)
	mux.HandleFunc("/api/v1/profile", profileHandler)
	mux.HandleFunc("/api/v1/device/register", deviceRegistrationHandler)
	mux.HandleFunc("/api/v1/admin/audit", requireRole("admin")(adminAuditHandler))

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Mobile API server starting on :8443")
	server.ListenAndServe()
}
